for (const [codes, zh, en] of guidance) for (const code of codes) { dictionaries.zh_CN.errors[code] = zh; dictionaries.en.errors[code] = en; }
// Every supported locale owns every product string; Japanese and Korean never fall back to English.
for (const [key, zh, en] of [

  ['helpData', '页头四个按钮可直接切换中文、English、日本語和 한국어。界面固定为深色。每个账号只存一份当前名单与有界记录；卸载前请导出 JSON 备份。', 'Use the four header buttons to choose Chinese, English, Japanese or Korean. The interface stays dark. Each account stores one current list with bounded history. Export a JSON backup before uninstalling.'],
  ['noDataDesc', '打开已登录的 X，点击“全面检查”。首次扫描建立基线，以后才能发现关系变化。', 'Open a signed-in X tab and click Full check. Your first scan creates a baseline for observing later relationship changes.'],
  ['mismatch', '这份快照与绑定账号不同，不能用于取关。全面检查会重新识别当前 X 账号。', 'This snapshot differs from the bound account and cannot be used for unfollowing. Full check identifies the current X account again.'],
  ['quickScan', '全面检查', 'Full check'], ['quickTitle', '看看你的互关', 'Check your connections'],
  
  ['advanced', '高级操作', 'Advanced controls'], ['phasePreparing', '正在自动准备', 'Preparing automatically'],
  ['preparingHint', '正在打开本人名单并准备读取，请稍候。', 'Opening your lists and preparing the reader. Please wait.'],
  ['scanLifecycle', '关闭弹窗后扫描仍可继续。', 'Scanning can continue after this popup closes.'],
  ['actionLifecycle', '关闭弹窗会停止后续取关；已发送的结果仍需核查。', 'Closing this popup stops subsequent unfollows. Sent requests still need confirmation.'],
  ['enableToScan', '高级扫描和取关需要开启助手；“全面检查”会自动开启并准备。', 'Advanced scans and unfollows require the helper. Full check enables and prepares it automatically.'],

  ['helpLanguage', '点击中文、EN、日本語或 한국어 按钮即可切换。蓝色表示当前语言；选择会保存在此浏览器。', 'Choose 中文, EN, 日本語 or 한국어 directly. Blue marks the current language. Your choice is saved in this browser.'],
  ['helpTheme', '界面使用固定深色显示。', 'The interface uses a fixed dark appearance.'],
  ['helpConnect', '高级操作：选择要使用的 X 标签并连接，核对本人账号。绑定只表示上次核实；取关前仍实时验证。', 'Advanced: select an X tab, connect it and check your account. Bound means last checked; actions verify the current identity again.'],
  ['helpRefresh', '重新读取本地任务和标签状态，不会开始扫描或发送账号操作。', 'Refresh local task and tab status. This does not start a scan or send an account action.'],
  ['helpOpenList', '在绑定的 X 标签打开本人名单，供高级读取准备原生模板。“全面检查”可自动完成准备。', 'Open your own list in the bound X tab to prepare native templates for advanced reads. Full check handles preparation automatically.'],
  ['helpSnapshot', '选择要查看的本地账号数据。这里的切换不会切换 X 登录账号；发送操作需要两者一致。', 'Choose stored account data to view. This does not switch the signed-in X account. Actions require these accounts to match.'],
  ['helpCSV', '导出当前分组、搜索和蓝标筛选后的全部结果，包含所有分页。CSV 供查看；恢复数据请用 JSON 备份。', 'Export all results matching this view, search and blue filter, across every page. CSV is for review; use JSON backups to restore data.'],
  ['helpSearch', '在当前分组中搜索名称、用户名和简介。清空搜索即可恢复列表。', 'Search names, usernames and bios within this view. Clear the search to restore the list.'],
  ['helpBlue', '只显示本次资料明确带蓝标的账号；蓝标不证明质量、身份或互关意愿。', 'Show accounts explicitly blue-verified in this observation. A badge does not prove quality, identity or an intention to follow back.'],
  ['helpSort', '改变当前结果的显示顺序，不修改 X 或历史记录。未知粉丝数不会当作已确认数字。', 'Change the display order without changing X or history. Unknown follower counts stay unknown.'],
  ['helpSelect', '选择本页账号后可忽略或逐项审核取关。选中不代表已授权发送；取关还需第二次确认。', 'Select accounts on this page to ignore or review for unfollowing. Selection is not authorization to send; unfollows need a separate confirmation.'],
  ['helpIgnore', '仅在本地隐藏或恢复账号，不改变 X 关系。已忽略账号不会进入取关队列。', 'Hide or restore an account locally. This does not change X relationships. Ignored accounts are excluded from unfollow actions.'],
  ['helpUnfollow', '先查看确切目标并二次确认，最多 20 个。需要本人匹配和 15 分钟内完整快照；逐人复核关系，未知即停止，不重发。', 'Review exact targets and confirm separately, up to 20. Requires a matching account and complete snapshot under 15 minutes old. Each relationship is checked; unknown results stop without retries.'],
  ['helpResolve', '只读查询原操作结果，绝不重新发送取关。目标不在当前名单时，未决记录仍保留在数据与设置。', 'Read the result of the original action without resending an unfollow. Unresolved records remain in Data & settings even if the target leaves the current list.'],
  ['helpBackup', '导出本地账号快照、忽略和有限记录为 JSON。文件含账号关系数据，请妥善保管。', 'Export local snapshots, ignores and bounded records as JSON. The file contains relationship data; store it privately.'],
  ['helpImport', '选择本助手的 JSON 备份并再次确认。同账号快照可能被替换，未决操作保留；建议先备份当前数据。', 'Choose a helper JSON backup and confirm. Matching snapshots may be replaced; unresolved actions remain protected. Back up current data first.'],
  ['helpRemove', '仅清除所选账号在本浏览器的数据，需要再次确认；不会取关。有未决操作时禁止清除。', 'Clear only the selected account’s data in this browser after another confirmation. No unfollows occur. Unresolved actions block clearing.'],
  ['helpProfile', '显示本地资料及可读取的补充信息。共同关注的样例与总数分别标注；未知不能解释为零。', 'Show local and available additional profile details. Known-follower examples and totals are labeled separately. Unknown never means zero.'],
  ['helpPagination', '每页最多 50 个账号。导出 CSV 会包含当前筛选下的全部分页。', 'Up to 50 accounts per page. CSV includes every page of the current filtered results.'],
  ['helpControl', '悬停或用键盘聚焦可查看说明；关闭对话框会放弃尚未确认的操作。', 'Hover or focus with the keyboard for guidance. Closing a dialog cancels actions that have not been confirmed.'],
]) { dictionaries.zh_CN[key] = zh; dictionaries.en[key] = en; }
